        [Fact]
        public void ConversionRoundTrip()
        {
            ThermalConductance wattperkelvin = ThermalConductance.FromWattsPerKelvin(3);
            Assert.Equal(3, ThermalConductance.FromWattsPerDegreeCelsius(wattperkelvin.WattsPerDegreeCelsius).WattsPerKelvin);
            Assert.Equal(3, ThermalConductance.FromWattsPerKelvin(wattperkelvin.WattsPerKelvin).WattsPerKelvin);
        }

        [Fact]
        public void ArithmeticOperators()
        {
            ThermalConductance v = ThermalConductance.FromWattsPerKelvin(1);
            Assert.Equal(-1, -v.WattsPerKelvin);
            Assert.Equal(2, (ThermalConductance.FromWattsPerKelvin(3) - v).WattsPerKelvin);
            Assert.Equal(2, (v + v).WattsPerKelvin);
            Assert.Equal(10, (v * 10).WattsPerKelvin);
            Assert.Equal(10, (10 * v).WattsPerKelvin);
            Assert.Equal(2, (ThermalConductance.FromWattsPerKelvin(10) / 5).WattsPerKelvin);
            Assert.Equal(2, ThermalConductance.FromWattsPerKelvin(10) / ThermalConductance.FromWattsPerKelvin(5));
        }

        [Fact]
        public void ComparisonOperators()
        {
            ThermalConductance oneWattPerKelvin = ThermalConductance.FromWattsPerKelvin(1);
            ThermalConductance twoWattsPerKelvin = ThermalConductance.FromWattsPerKelvin(2);

            Assert.True(oneWattPerKelvin < twoWattsPerKelvin);
            Assert.True(oneWattPerKelvin <= twoWattsPerKelvin);
            Assert.True(twoWattsPerKelvin > oneWattPerKelvin);
            Assert.True(twoWattsPerKelvin >= oneWattPerKelvin);

            Assert.False(oneWattPerKelvin > twoWattsPerKelvin);
            Assert.False(oneWattPerKelvin >= twoWattsPerKelvin);
            Assert.False(twoWattsPerKelvin < oneWattPerKelvin);
            Assert.False(twoWattsPerKelvin <= oneWattPerKelvin);
        }

        [Fact]
        public void CompareToIsImplemented()
        {
            ThermalConductance wattperkelvin = ThermalConductance.FromWattsPerKelvin(1);
            Assert.Equal(0, wattperkelvin.CompareTo(wattperkelvin));
            Assert.True(wattperkelvin.CompareTo(ThermalConductance.Zero) > 0);
            Assert.True(ThermalConductance.Zero.CompareTo(wattperkelvin) < 0);
        }

