        public void Equals_ReturnsTrue_IfValueAndUnitAreEqual(double valueA, ThermalConductanceUnit unitA, double valueB, ThermalConductanceUnit unitB, bool expectEqual)
        {
            var a = new ThermalConductance(valueA, unitA);
            var b = new ThermalConductance(valueB, unitB);

            // Operator overloads.
            Assert.Equal(expectEqual, a == b);
            Assert.Equal(expectEqual, b == a);
            Assert.Equal(!expectEqual, a != b);
            Assert.Equal(!expectEqual, b != a);

            // IEquatable<T>
            Assert.Equal(expectEqual, a.Equals(b));
            Assert.Equal(expectEqual, b.Equals(a));

            // IEquatable
            Assert.Equal(expectEqual, a.Equals((object)b));
            Assert.Equal(expectEqual, b.Equals((object)a));
        }

